const round2 = x => Math.round(x*100)/100;

for (const [name, r] of [["6%",0.06],["8%",0.08],["10%",0.10]]) {
  const i = r/12;
  const f = (1 - Math.pow(1+i,-36))/i;
  const p = 18000*f;
  console.log(name, "factor:", f.toFixed(6), "PV exact:", p.toFixed(4), "PV $:", round2(p).toLocaleString());
}

// roll-forward at 8%
const i08 = 0.08/12;
let bal = 18000*(1 - Math.pow(1+i08,-36))/i08;
console.log("PV at 8% cents:", round2(bal));
let ints=[], b=bal;
for (let m=1;m<=3;m++){
  const it = round2(b*i08);
  ints.push(it);
  const end = round2(b + it - 18000);
  console.log(`month${m}: open ${round2(b)} + interest ${it} - 18000 -> ${end}`);
  b = end;
}
console.log("ending balance cents:", round2(b), "interest sum:", ints.join('+'), "=", round2(ints.reduce((a,c)=>a+c,0)));

// front-loaded alternative
const amortQ = (18000*(1 - Math.pow(1+i08,-36))/i08)/36*3;
const intQ = round2(ints.reduce((a,c)=>a+c,0));
console.log("amort Q4:", round2(amortQ), "int Q4:", intQ, "total FL:", round2(amortQ+intQ), "loss alt:", -234000 + round2(amortQ+intQ) - 54000);
console.log("SL expense:", round2(18000*(1 - Math.pow(1+i08,-36))/i08/3), "x3 =", 54000);

// materiality / covenant / P&L
console.log("690/1540 %:", (690000/1540000*100).toFixed(2));
console.log("690/850 %:", (690000/850000*100).toFixed(2));
console.log("covenant shortfall:", 1500000-850000);
const drafted = 850000+480000+210000, niD = drafted-54000-712000-318000;
console.log("drafted:", drafted, drafted-480000-210000, "corrected NI:", (drafted-690000)-54000-712000-318000, "drafted NI:", niD);

// 13-week reconciliation
const weeks=[[535000,118000,195000,612000],[430000,96000,201000,535000],[384000,142000,188000,430000],[236000,88000,236000,384000],[165000,104000,175000,236000],[50000,97000,212000,165000],[8000,140000,182000,50000],[-105000,92000,205000,8000],[-165000,110000,170000,-105000],[-281000,98000,214000,-165000],[-337000,120000,176000,-281000],[-445000,101000,209000,-337000],[-509000,118000,182000,-445000]];
let ok=true, neg=[];
weeks.forEach(([end,rec,dis,beg],idx)=>{ if(beg+rec-dis!==end){ok=false;console.log("MISMATCH wk",idx+1);} if(end<0)neg.push(idx+1); });
console.log("cash flow reconciles:", ok, "| negative weeks:", neg.length, "| first:", neg[0], "| week8 end:", weeks[7][0], "| week13 end:", weeks[12][0]);

